// Command api is the Ortus HTTP API with the BFF session endpoints (W0.09): chi, slog JSON, HTTP_ADDR from the
// environment. Every contract operation goes through the gateway (gate.go); the routes of the OpenAPI tags are
// generated by `make gen` (router.go, tools/gen/codegen.mjs). Configuration: deploy/compose/.env.example.
//
// Exit codes: 0 — stopped by a signal; 1 — server failure; 2 — configuration or database unreachable at start.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"

	"github.com/ortus/ortus-crm/backend/internal/control/tenants/platformhttp"
	"github.com/ortus/ortus-crm/backend/internal/modules/access/invitations"
	"github.com/ortus/ortus-crm/backend/internal/platform/authz"
	"github.com/ortus/ortus-crm/backend/internal/platform/idem"
	"github.com/ortus/ortus-crm/backend/internal/platform/notify/inbox"
	"github.com/ortus/ortus-crm/backend/internal/platform/session"
	"github.com/ortus/ortus-crm/backend/internal/platform/session/oidc"
	"github.com/ortus/ortus-crm/backend/internal/platform/session/oidc/authhttp"
	"github.com/ortus/ortus-crm/backend/internal/platform/tenantctx"
	"github.com/ortus/ortus-crm/backend/internal/platform/tenantctx/mehttp"
)

const (
	exitOK     = 0
	exitFailed = 1
	exitConfig = 2
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	code := run(ctx, os.Getenv, os.Stdout, os.Stderr)
	stop()
	os.Exit(code)
}

func run(ctx context.Context, getenv func(string) string, stdout, stderr io.Writer) int {
	cfg, err := loadConfig(getenv)
	if err != nil {
		fmt.Fprintf(stderr, "api: configuration: %v\n", err)
		return exitConfig
	}
	log := slog.New(slog.NewJSONHandler(stdout, &slog.HandlerOptions{Level: cfg.LogLevel}))
	d, closeDeps, err := build(ctx, cfg, log, getenv)
	if err != nil {
		fmt.Fprintf(stderr, "api: %v\n", err)
		return exitConfig
	}
	defer closeDeps()

	srv := &http.Server{
		Addr:              cfg.HTTPAddr,
		Handler:           newHandler(d),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       2 * time.Minute,
		ErrorLog:          slog.NewLogLogger(log.Handler(), slog.LevelWarn),
	}
	errc := make(chan error, 1)
	go func() { errc <- srv.ListenAndServe() }()
	log.InfoContext(ctx, "api: listening", slog.String("addr", cfg.HTTPAddr), slog.String("app_env", cfg.AppEnv),
		slog.String("auth_provider", cfg.AuthProvider))
	select {
	case err := <-errc:
		log.ErrorContext(ctx, "api: server failed", slog.String("error", err.Error()))
		return exitFailed
	case <-ctx.Done():
	}
	shutdown, cancel := context.WithTimeout(context.WithoutCancel(ctx), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdown); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.ErrorContext(ctx, "api: shutdown", slog.String("error", err.Error()))
		return exitFailed
	}
	return exitOK
}

// tenantStore joins what GET /me/context reads from tenant DBs: the profile (TenantData) and the capabilities
// (the evaluator of W1.04 over the same grants).
type tenantStore struct {
	tenantctx.TenantData
	*authz.Evaluator
}

// newEvaluator is the permission evaluator of W1.04 over the tenant pools, with the clock of the application
// (APP_FIXED_NOW outside prod).
func newEvaluator(pools *tenantctx.Pools, cfg config) *authz.Evaluator {
	src := authz.PGSource{Pools: pools}
	return authz.New(src, src, cfg.clock())
}

// build connects the control DB (role ortus_api) and wires the platform: directory, tenant pools (secret_ref +
// sentinel), the permission evaluator, durable BFF sessions in the control DB (W1.03), the idempotency guard, the
// strict servers of the tags Context (with selectTenant) and Auth (OIDC sign-in, logout, invitations), Platform.
func build(ctx context.Context, cfg config, log *slog.Logger, getenv func(string) string) (deps, func(), error) {
	pcfg, err := pgxpool.ParseConfig(cfg.ControlDBURL)
	if err != nil {
		return deps{}, nil, errors.New("CONTROL_DB_URL is not a valid PostgreSQL DSN") // the parse error quotes the DSN
	}
	control, err := pgxpool.NewWithConfig(ctx, pcfg)
	if err != nil {
		return deps{}, nil, fmt.Errorf("control DB: %w", err)
	}
	if err := control.Ping(ctx); err != nil {
		control.Close()
		return deps{}, nil, fmt.Errorf("control DB %s/%s unreachable: %w", pcfg.ConnConfig.Host, pcfg.ConnConfig.Database, err)
	}
	dir := tenantctx.NewPGDirectory(control)
	pools := tenantctx.NewPools(dir, getenv, cfg.TenantDBHost)
	// S1-02 (W1.02): the control DB is never a tenant DB, whatever its name.
	pools.Reserved = []string{pcfg.ConnConfig.Database}
	controlSQL := stdlib.OpenDBFromPool(control)
	data := tenantctx.TenantData{Pools: pools}
	ev := newEvaluator(pools, cfg)
	sessions := oidc.NewPGSessionStore(control) // Q-W0.09-8: sessions survive the process and serve every replica
	manager := &session.Manager{
		CookieName: cfg.SessionCookie, CSRFCookieName: csrfCookie, TTL: cfg.SessionTTL,
		AllowedOrigins: cfg.AllowedOrigins, Secure: cfg.CookieSecure, Store: sessions,
	}
	auth := &authhttp.Server{
		Sessions: manager, Logins: oidc.NewPGLoginStore(control), Providers: providers(cfg),
		Accounts: oidc.NewPGAccounts(control), Revoker: sessions,
		Invitations: &invitations.Service{Control: control, Tenants: pools}, Log: log,
	}
	d := deps{
		cfg:      cfg,
		log:      log,
		dir:      dir,
		sessions: manager,
		authz:    authz.Gateway{E: ev},
		servers: Servers{
			Context: &mehttp.Server{
				Dir: dir, TenantDB: tenantStore{TenantData: data, Evaluator: ev},
				LastTenants: mehttp.NewPGLastTenants(control), Log: log,
				Inbox: &inbox.Inbox{Pools: pools, Audience: inbox.AuthzAudience{E: ev}}, // W1.10: /me/notifications
			},
			Auth:     auth,
			Platform: &platformhttp.Server{Store: platformhttp.SQLStore{Control: controlSQL}},
		},
		replays: map[string]replayFunc{"logout": auth.ReplayLogout},
		ready:   control.Ping,
		// S1-25: tenant keys in core.idempotency_keys of the tenant DB; identity and platform operations have no
		// table in the control DB yet and keep their keys in memory (brief W1.01 §10 item 1).
		idem: &idem.Guard{Stores: idem.TenantStores{Pools: pools, Platform: idem.NewMemStore()}, Log: log},
	}
	return d, func() {
		pools.Close()
		_ = controlSQL.Close()
		control.Close()
	}, nil
}

// providers are the OIDC clients of the configuration: the realm of clients and, if set, of operators.
func providers(cfg config) authhttp.Providers {
	var out authhttp.Providers
	for key, p := range map[string]*providerConfig{authhttp.ProviderUsers: cfg.Users, authhttp.ProviderOperators: cfg.Operators} {
		if p != nil {
			out = append(out, oidc.NewProvider(oidc.Config{
				Key: key, Issuer: p.Issuer, ClientID: p.ClientID, ClientSecret: p.ClientSecret,
				RedirectURL: p.RedirectURL, PostLogoutRedirectURL: p.PostLogoutRedirectURL,
			}))
		}
	}
	return out
}
